<?php require 'db.php';require 'helpers.php';require_admin();$rows=$pdo->query('SELECT a.*,u.name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 200')->fetchAll();page_header('Audit Logs');?><section class="panel"><h2>Audit Log (latest 200)</h2><table><tr><th>When</th><th>User</th><th>Action</th><th>Details</th><th>IP</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name']??'Deleted user')?></td><td><?=e($r['action'])?></td><td><?=e($r['details'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endforeach;?></table></section><?php page_footer();?>